using BCrypt.Net;

// Hash on registration: workFactor controls the cost
string hash = BCrypt.HashPassword(plainPassword, workFactor: 12);
// "$2a$12$..." — salt and cost are embedded

// Verify on login
bool ok = BCrypt.Verify(attempt, storedHash);

// Rehash transparently when the work factor is raised
if (ok && BCrypt.PasswordNeedsRehash(storedHash, 12))
{
    user.PasswordHash = BCrypt.HashPassword(attempt, 12);
